// Фикстура теста музыкальных слоёв (§25).
//
// Звуков в фикстуре нет: тест сам генерирует WAV во временном каталоге и
// передаёт абсолютные пути в $.sound.stems() — так проверяются реальные
// PCM-позиции транспорта, а не заранее заготовленный файл.
//
// Здесь — только мир и шина музыки, чтобы сцена жила и была куда играть звук.
$.ready(() => {
    $.world.color('#101820').bounds(0, 0, 640, 360);
    $.audio.bus('music', { volume: 1 });
    $.audio.bus('ui', { volume: 1 });
    $.audio.bus('ambience', { volume: 1, effect: 'reverb', effectParams: { send: 0.4 } });
    $('<rect>', { id: 'marker' }).at(20, 20).size(12, 12).color('#ffd34d').appendTo($.world);
});
